#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <math.h>

/* Compute the sum of proper divisors of n (n > 0). */
static long sum_proper_divisors(long n) {
    if (n <= 1) return 0; // 1 has no proper divisors
    long sum = 1; // 1 is always a proper divisor
    long limit = (long)sqrt((double)n);
    for (long d = 2; d <= limit; ++d) {
        if (n % d == 0) {
            long other = n / d;
            sum += d;
            if (other != d) sum += other;
        }
    }
    return sum;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long sum = sum_proper_divisors(n);
    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }
    return 0;
}
